-- Guest Hub S1b (25 Nov 2026, Ahmed — DECISIONS.md 2026-11-25 «Guest Hub S1b»): «السوشيال» judged by its own lab and its
-- own licences; the lab's context with the channel's kind; the social bank as lab items. Generated by
-- scripts/hub-s1b-migration.mjs — never edited once applied (CLAUDE.md §12).
-- No unit mode, licence or switch changes. No phone number in this file. Every UPDATE / DELETE carries a WHERE.

create or replace function public.hub_eval_context(p_unit text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare u public.hub_units;
begin
  select * into u from public.hub_units where key = p_unit;
  if u.id is null then raise exception 'hub_unit' using errcode = '22023'; end if;
  return jsonb_build_object(
    'unit', jsonb_build_object('id', u.id, 'key', u.key, 'kind', u.kind, 'branch', u.branch_slug, 'name_ar', u.name_ar, 'name_en', u.name_en,
      'mode', 'test', 'skills', to_jsonb(u.skills), 'persona', u.persona_live,
      'venue', (select jsonb_build_object('name_ar', v.name_ar, 'name_en', v.name_en, 'menu', v.menu) from public.dining_venues v where v.id = u.dining_venue_id)),
    -- S1b: the channel's kind and provider (a Meta channel asks the mobile number for a booking)
    'channel', (select jsonb_build_object('address', ch.address, 'sending_enabled', false, 'kind', ch.kind, 'provider', ch.provider) from public.hub_channels ch where ch.unit_id = u.id order by ch.created_at limit 1),
    'licences', (select coalesce(jsonb_object_agg(l.topic_key, l.mode), '{}') from public.hub_licences l where l.unit_id = u.id),
    'topics', (select coalesce(jsonb_agg(jsonb_build_object('key', x.key, 'label_en', x.label_en, 'label_ar', x.label_ar, 'parent_key', x.parent_key, 'always_handoff', x.always_handoff) order by x.sort, x.key), '[]')
                 from public.hub_topics x where x.status = 'active' and not x.is_test),
    'settings', jsonb_build_object(
      'confidence_floor', coalesce((select (s.value #>> '{}')::numeric from public.settings s where s.key = 'hub_confidence_floor'), 0.7),
      'cards_per_turn', internal.hub_setting_int('hub_cards_per_turn', 5), 'reply_max_chars', internal.hub_setting_int('hub_reply_max_chars', 600),
      'failed_max', internal.hub_setting_int('hub_failed_understanding_max', 2), 'group_min_rooms', internal.hub_setting_int('hub_group_min_rooms', 5),
      'models', (select s.value from public.settings s where s.key = 'hub_models'), 'prices', (select s.value from public.settings s where s.key = 'hub_model_prices'),
      'show_prices', coalesce((select case when u.branch_slug is null then (s.value ->> 'airport-road')::boolean and (s.value ->> 'shafa-road')::boolean
                                           else (s.value ->> u.branch_slug)::boolean end from public.settings s where s.key = 'show_prices'), false)),
    'forbidden', to_jsonb(internal.hub_forbidden_terms()),
    'fees', jsonb_build_object('breakfast', (select s.value from public.settings s where s.key = 'breakfast'),
                               'extra_bed_per_night', (select (s.value #>> '{}')::numeric from public.settings s where s.key = 'extra_bed_per_night')),
    'cards', (select coalesce(jsonb_object_agg(k.key, jsonb_build_object('ar', k.live ->> 'text_ar', 'en', k.live ->> 'text_en')), '{}')
                from public.hub_knowledge_cards k where k.status = 'published' and k.live is not null and k.key like 'k-wifi-password-%'),
    'budget', internal.hub_budget_state(),
    'today', internal.riyadh_today());
end;
$$;

create or replace function internal.hub_test_lab_ready(u public.hub_units) returns boolean
language sql stable security definer set search_path = '' as $$
  -- S1b: every unit by its OWN latest full run («السوشيال» included — its own questions)
  select (internal.hub_unit_lab(u) ->> 'run_id') is not null and jsonb_array_length(coalesce(internal.hub_unit_lab(u) -> 'blocking', '[]'::jsonb)) = 0
     and coalesce((internal.hub_unit_lab(u) ->> 'items')::int, 0) > 0
$$;

create or replace function public.hub_turn_claim(p_turn uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  t public.hub_turns;
  c public.hub_conversations;
  u public.hub_units;
  ch public.hub_channels;
  g public.guest_profiles;
  st jsonb;
  v_mode text;
  v_state text;
  v_draft jsonb;
  v_first boolean;
  v_rate jsonb;
  v_text text;
  v_phase text;
begin
  select * into t from public.hub_turns where id = p_turn for update skip locked;
  if t.id is null then return jsonb_build_object('claimed', false, 'reason', 'taken'); end if;
  if t.status <> 'pending' then return jsonb_build_object('claimed', false, 'reason', t.status); end if;
  if t.due_at > now() then return jsonb_build_object('claimed', false, 'reason', 'not_due', 'due_at', t.due_at); end if;
  -- H11 (Ahmed, 24 Nov 2026 — «تم، أضفنا ذلك إلى طلبك.» twice in 5 seconds): the turns of one conversation one at a time —
  -- the conversation is locked BEFORE looking for a running turn, so a second claim waits for the first to commit and sees it
  perform 1 from public.hub_conversations where id = t.conversation_id for update;
  if exists (select 1 from public.hub_turns x where x.conversation_id = t.conversation_id and x.status = 'running') then
    return jsonb_build_object('claimed', false, 'reason', 'busy');
  end if;
  select * into c from public.hub_conversations where id = t.conversation_id for update;
  select * into u from public.hub_units where id = c.unit_id;
  select * into ch from public.hub_channels where id = c.channel_id;
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  -- S1: a brand unit («السوشيال») answers for the conversation's branch once the guest named it (NULL until then)
  if u.kind = 'brand' then u.branch_slug := c.branch_slug; end if;
  st := internal.hub_assistant_state(u);
  if c.state = 'closed' or not (st ->> 'active')::boolean or g.hub_blocked_at is not null then
    update public.hub_turns set status = 'skipped', finished_at = now(), error = coalesce(case when c.state = 'closed' then 'closed' when g.hub_blocked_at is not null then 'blocked' end, st ->> 'reason') where id = t.id;
    perform internal.hub_to_team(c, coalesce(st ->> 'reason', 'assistant_off'));
    return jsonb_build_object('claimed', false, 'reason', coalesce(st ->> 'reason', 'closed'));
  end if;
  v_mode := case st ->> 'mode' when 'test' then 'test' when 'shadow' then 'shadow' else 'live' end;
  v_state := case when v_mode = 'test' then coalesce(c.test_state, 'new') else c.state end;
  -- H6c: waiting (handed, no staff reply) / resume (staff silent for the branch's minutes) / null (silent)
  v_phase := case when v_mode = 'test' then case when v_state = 'human' then 'waiting' end when c.state = 'human' then internal.hub_human_phase(c, u) end;
  update public.hub_turns set status = 'running', claimed_at = now(), started_at = coalesce(started_at, now()), attempts = attempts + 1, mode = v_mode,
                              kind = case when v_state = 'closed' or (v_state = 'human' and v_phase is null) then 'tag' else kind end,
                              -- «وضع الاستعداد»: no staff reply in the wait — the assistant answers after it
                              standby_outcome = case when standby_until is not null and standby_outcome is null and kind = 'reply'
                                                       and not (v_state = 'closed' or (v_state = 'human' and v_phase is null)) then 'assistant' else standby_outcome end
   where id = t.id returning * into t;
  select to_jsonb(d) - 'is_test' into v_draft from public.hub_drafts d where d.conversation_id = c.id and d.status = 'open' and d.sim = (v_mode = 'test');
  v_first := not exists (select 1 from public.hub_messages m where m.conversation_id = c.id and m.direction = 'out' and m.kind <> 'note'
                          and m.status not in ('rejected', 'superseded', 'failed') and (v_mode = 'test' or m.status <> 'test'));
  select string_agg(m.body, ' ' order by m.sent_at) into v_text from public.hub_messages m where m.id = any (t.inbound_message_ids);
  -- the rate limits of spec §7.4: guest messages processed per phone per hour, assistant replies per conversation per
  -- hour, the same text three times in ten minutes
  v_rate := jsonb_build_object(
    'phone_hour', (select coalesce(sum(cardinality(x.inbound_message_ids)), 0) from public.hub_turns x join public.hub_conversations y on y.id = x.conversation_id
                    where y.guest_profile_id = g.id and x.id <> t.id and x.status in ('done', 'running') and x.kind = 'reply' and x.created_at > now() - interval '1 hour'),
    -- H10 (bd27baf4 — three cards counted as three replies): the assistant's replies by TURN
    'replies_hour', (select count(distinct m.turn_id) from public.hub_messages m where m.conversation_id = c.id and m.author = 'assistant' and m.direction = 'out'
                      and m.created_at > now() - interval '1 hour' and not coalesce((m.payload ->> 'notice')::boolean, false)),
    'repeated', (select count(*) >= 2 from public.hub_messages m where m.conversation_id = c.id and m.direction = 'in' and m.author = 'guest'
                  and not (m.id = any (t.inbound_message_ids)) and m.created_at > now() - interval '10 minutes'
                  and btrim(lower(coalesce(m.body, ''))) = btrim(lower(coalesce(v_text, ''))) and coalesce(v_text, '') <> '')
                  -- Ahmed, 14 Nov 2026 (H6 pass 4): a repeat is suppressed ONLY when the assistant already answered that same text in
                  -- this episode, and answered its LATEST earlier copy (that copy's reply turn sent the guest a message) — so a copy
                  -- whose earlier copies got no reply from the assistant (the team owned the conversation, the model failed …) is
                  -- answered; 21:51 of 14 Nov: the 21:48 copies came while the phone owned it, so the third is answered
                  and coalesce((select exists (select 1 from public.hub_turns z join public.hub_messages o on o.turn_id = z.id
                                                where z.conversation_id = c.id and m2.id = any (z.inbound_message_ids) and z.kind = 'reply' and z.status = 'done'
                                                  and o.direction = 'out' and o.author = 'assistant' and o.status not in ('test', 'rejected', 'superseded', 'failed'))
                                  from public.hub_messages m2
                                 where m2.conversation_id = c.id and m2.direction = 'in' and m2.author = 'guest' and not (m2.id = any (t.inbound_message_ids))
                                   and btrim(lower(coalesce(m2.body, ''))) = btrim(lower(coalesce(v_text, '')))
                                 order by m2.created_at desc, m2.sent_at desc, m2.id desc limit 1), false),
    'phone_max', internal.hub_setting_int('hub_rate_phone_hour', 30), 'replies_max', internal.hub_setting_int('hub_rate_replies_hour', 20));
  return jsonb_build_object(
    'claimed', true,
    'turn', jsonb_build_object('id', t.id, 'kind', t.kind, 'mode', v_mode, 'attempts', t.attempts, 'is_test', t.is_test),
    'conversation', jsonb_build_object('id', c.id, 'state', v_state, 'real_state', c.state, 'state_before_human', c.state_before_human, 'human_phase', v_phase, 'human_reason', c.human_reason,
      'language', coalesce(c.language, g.language), 'window_expires_at', c.window_expires_at, 'failed_understandings', c.failed_understandings,
      'priority', c.priority, 'topics', to_jsonb(c.topics), 'tags', to_jsonb(c.tags), 'out_of_scope', c.out_of_scope, 'first_reply', v_first,
      'created_at', c.created_at, 'is_test', c.is_test, 'branch', c.branch_slug, 'branch_pending', c.branch_pending),
    'unit', jsonb_build_object('id', u.id, 'key', u.key, 'kind', u.kind, 'branch', u.branch_slug, 'name_ar', u.name_ar, 'name_en', u.name_en,
      'mode', u.assistant_mode, 'skills', to_jsonb(u.skills), 'persona', u.persona_live,
      -- H7: «الفويس» and «الصور»
      'media', jsonb_build_object('voice', u.voice_on, 'images', u.images_on),
      'venue', (select jsonb_build_object('name_ar', v.name_ar, 'name_en', v.name_en, 'menu', v.menu) from public.dining_venues v where v.id = u.dining_venue_id)),
    'channel', jsonb_build_object('address', ch.address, 'sending_enabled', ch.sending_enabled, 'kind', ch.kind, 'provider', ch.provider),
    'guest', jsonb_build_object(
      -- a name from a past booking only (spec §2.9) — never the WhatsApp profile name
      'first_name', case when exists (select 1 from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and not r.is_test)
                         then nullif(split_part(btrim(coalesce(g.name, '')), ' ', 1), '') end,
      'returning', exists (select 1 from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and r.check_out <= internal.riyadh_today() and not r.is_test),
      'language', g.language,
      -- H8: a returning guest's previous room (a confirmed past stay on the same phone) — its card comes first
      'last_room', (select jsonb_build_object('branch', r.branch, 'room', rt.slug) from public.reservations r join public.room_types rt on rt.id = r.room_type_id
                     where r.phone = g.phone and r.status = 'confirmed' and not r.is_test and r.check_out <= internal.riyadh_today() order by r.check_out desc limit 1),
      -- H8: the «إياب» members' prices only for a member with recorded consent (applied by code, never inferred)
      'member', g.club_joined_at is not null and g.consent = 'granted',
      -- H8: «يُعامَل كضيف للتجربة» — a test reservation that never takes a room
      'test_guest', internal.hub_test_guest(g.phone)),
    -- H8: the live «إياب» members' codes of this branch, for a member only
    'member_codes', case when g.club_joined_at is not null and g.consent = 'granted' then
      (select coalesce(jsonb_agg(distinct o.promo_code), '[]'::jsonb) from public.offers o
        where o.audience = 'members' and o.category = 'individuals' and o.live is not null and o.archived_at is null and not o.is_test and o.promo_code is not null
          and (o.valid_to is null or o.valid_to >= internal.riyadh_today()) and (o.branches is null or cardinality(o.branches) = 0 or u.branch_slug is null or u.branch_slug = any (o.branches)))
      else '[]'::jsonb end,
    'messages', (select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'kind', m.kind, 'body', m.body, 'payload', m.payload, 'sent_at', m.sent_at,
                                                              'provider_message_id', m.provider_message_id,
                                                              -- H7: the stored file and a transcript already made (a retried turn)
                                                              'media_path', m.media_path, 'media_mime', m.media_mime, 'transcript', m.transcript) order by m.sent_at, m.created_at), '[]')
                   from public.hub_messages m where m.id = any (t.inbound_message_ids)),
    'history', (select coalesce(jsonb_agg(jsonb_build_object('author', case when h.direction = 'in' then 'guest' when h.author in ('staff', 'phone') then 'staff' else 'us' end, 'body', coalesce(h.body, h.transcript), 'kind', h.kind, 'at', h.sent_at) order by h.sent_at), '[]')
                  from (select m.* from public.hub_messages m
                         where m.conversation_id = c.id and not (m.id = any (t.inbound_message_ids)) and m.kind <> 'note' and coalesce(m.body, m.transcript) is not null
                           and m.status not in ('rejected', 'superseded', 'failed', 'pending_approval') and (v_mode = 'test' or m.status <> 'test')
                         order by m.sent_at desc limit 12) h),
    'draft', v_draft,
    -- H9: a departure check sent today and not answered yet — a typed answer («بمدد يومين», «طالع الساعة 11») is understood
    -- as «سأغادر في موعدي» / «أرغب في التمديد»; a late check-out question stays an ordinary question
    'departure', (select jsonb_build_object('id', d.id, 'ref', d.nazeel_ref) from public.hub_departures d
                   where d.phone = g.phone and d.branch_slug = u.branch_slug and d.answer is null and d.is_test = c.is_test
                     and d.check_state in ('accepted', 'sent', 'delivered', 'read', 'test') and d.departure_date = internal.riyadh_today()
                   order by d.check_at desc limit 1),
    -- H7: the unit's transcribed seconds today and the cap
    'voice', internal.hub_voice_state(u.id),
    -- the guest's own bookings (same phone) for a booking-status answer: ref, status, branch, dates only
    -- H10: with the room, the party, breakfast and the recorded cancellation (a reply never contradicts it; the alternatives
    -- of a cancelled stay)
    'bookings', (select coalesce(jsonb_agg(jsonb_build_object('ref', r.ref, 'status', r.status, 'branch', r.branch, 'check_in', r.check_in, 'check_out', r.check_out,
                                           'room', (select rt.slug from public.room_types rt where rt.id = r.room_type_id), 'adults', r.adults, 'children', r.children,
                                           'breakfast', r.breakfast, 'cancel_reason_code', r.cancel_reason_code, 'cancelled_at', r.cancelled_at, 'source', r.booking_source)
                                           order by r.check_in desc), '[]')
                   from (select * from public.reservations r where r.phone = g.phone and (r.is_test = c.is_test or (r.is_test and internal.hub_test_guest(g.phone)))
                          order by r.created_at desc limit 5) r),
    -- H10: every message we sent this guest outside the chat's text in the last 7 days — the booking templates (rendered by
    -- the engine with the variables they carried), the departure check, the review request, the arrival reminder; no phone
    'sent', (select coalesce(jsonb_agg(s.j order by s.at), '[]') from (
               select w.created_at as at, jsonb_build_object('at', w.created_at, 'template', w.template, 'meta_template', w.meta_template, 'language', w.language,
                        'status', w.status, 'ref', r.ref, 'branch', r.branch, 'check_in', r.check_in, 'check_out', r.check_out, 'total', r.total,
                        'room', (select rt.slug from public.room_types rt where rt.id = r.room_type_id), 'room_name_ar', r.room_name_ar, 'room_name_en', r.room_name_en,
                        'first_name', split_part(btrim(coalesce(r.guest_name, '')), ' ', 1), 'reason_code', coalesce(w.reason_code, r.cancel_reason_code)) as j
                 from public.whatsapp_messages w join public.reservations r on r.id = w.reservation_id
                where r.phone = g.phone and w.is_test = c.is_test and w.status not in ('failed', 'queued') and w.created_at > now() - interval '7 days'
               union all
               select e.created_at, jsonb_build_object('at', e.created_at, 'template', e.template, 'language', e.language, 'status', e.status)
                 from public.eyab_messages e
                where e.profile_id = g.id and e.is_test = c.is_test and e.status not in ('failed', 'queued') and e.created_at > now() - interval '3 days'
                  and e.template in ('stay_review', 'arrival_reminder', 'eyab_welcome', 'eyab_offer')
               union all
               select d.check_at, jsonb_build_object('at', d.check_at, 'template', 'stay_checkout_check', 'status', d.check_state)
                 from public.hub_departures d
                where d.phone = g.phone and d.is_test = c.is_test and d.check_at is not null and d.check_at > now() - interval '3 days'
                  and d.check_state in ('accepted', 'sent', 'delivered', 'read', 'test')
               order by 1 desc limit 8) s),
    -- H10: the hand-off notice ONCE per hand-off episode — whether it already went since the hand-off (no staff reply since),
    -- and whether «ما زال طلبك…» is due (30 minutes since our last message)
    'handoff', case when c.state = 'human' and c.owner_kind is null then jsonb_build_object(
                 'notice_open', exists (select 1 from public.hub_messages m where m.conversation_id = c.id and m.author = 'assistant' and m.direction = 'out'
                                          and m.created_at >= c.state_changed_at and m.status not in ('failed', 'rejected', 'superseded')
                                          and (coalesce((m.payload ->> 'notice')::boolean, false) or coalesce((m.payload ->> 'handoff')::boolean, false))),
                 'waiting_line_due', coalesce((select max(m.created_at) from public.hub_messages m where m.conversation_id = c.id and m.author = 'assistant' and m.direction = 'out'
                                                and m.status not in ('failed', 'rejected', 'superseded')), c.state_changed_at) <= now() - interval '30 minutes')
               end,
    -- H10 (5fb7aac4): a staff or phone message of the last 3 hours asked about leaving or extending («خروج ولا تمديد؟»)
    'staff_departure_q', exists (select 1 from public.hub_messages m where m.conversation_id = c.id and m.direction = 'out' and m.author in ('staff', 'phone')
                                   and m.created_at > now() - interval '3 hours' and coalesce(m.body, '') ~* '(خروج|تمديد|مغادر|تطلع|تغادر|تمدد|check ?out|extend|leaving)'),
    -- S1b: every unit by its OWN licences («التراخيص»; «السوشيال» starts «بموافقة الفريق» — the system admin sets them)
    'licences', (select coalesce(jsonb_object_agg(l.topic_key, l.mode), '{}') from public.hub_licences l where l.unit_id = u.id),
    'topics', (select coalesce(jsonb_agg(jsonb_build_object('key', x.key, 'label_en', x.label_en, 'label_ar', x.label_ar, 'parent_key', x.parent_key, 'always_handoff', x.always_handoff) order by x.sort, x.key), '[]')
                 from public.hub_topics x where x.status = 'active' and not x.is_test),
    'settings', jsonb_build_object(
      'confidence_floor', coalesce((select (s.value #>> '{}')::numeric from public.settings s where s.key = 'hub_confidence_floor'), 0.7),
      'cards_per_turn', internal.hub_setting_int('hub_cards_per_turn', 5), 'reply_max_chars', internal.hub_setting_int('hub_reply_max_chars', 600),
      'failed_max', internal.hub_setting_int('hub_failed_understanding_max', 2), 'resume_minutes', internal.hub_resume_minutes(u.branch_slug), 'group_min_rooms', internal.hub_setting_int('hub_group_min_rooms', 5),
      'models', (select s.value from public.settings s where s.key = 'hub_models'), 'prices', (select s.value from public.settings s where s.key = 'hub_model_prices'),
      -- the site's own switch: prices only while the branch shows them (spec §2.5 rule 11)
      'show_prices', coalesce((select case when u.branch_slug is null then (s.value ->> 'airport-road')::boolean and (s.value ->> 'shafa-road')::boolean
                                           else (s.value ->> u.branch_slug)::boolean end from public.settings s where s.key = 'show_prices'), false),
      -- H8: the branch's «الحجز الفوري» (off keeps the booking link as the fallback) and the instant limits (the reason texts)
      'instant_booking', coalesce((select case when u.branch_slug is null then (s.value ->> 'airport-road')::boolean and (s.value ->> 'shafa-road')::boolean
                                               else (s.value ->> u.branch_slug)::boolean end from public.settings s where s.key = 'instant_booking'), false),
      'limits', coalesce(internal.setting('instant_limits'), '{"same_day_cutoff": "20:00", "max_nights": 30}'::jsonb)),
    -- the shared forbidden list the guard reads (internal.hub_forbidden_terms — never copied)
    'forbidden', to_jsonb(internal.hub_forbidden_terms()),
    'rate', v_rate,
    'budget', internal.hub_budget_state(),
    'today', internal.riyadh_today());
end;
$$;

-- the social bank's engine conversations as lab items of «السوشيال» (the deletion items are the router's)
do $$
declare v_sort integer := coalesce((select max(sort) from public.hub_test_items), 0) + 1;
begin
  insert into public.hub_test_items (key, unit_key, language, messages, context, expect, note, tags, added_from, sort)
  select e ->> 'key', e ->> 'unit', e ->> 'language', e -> 'messages', coalesce(e -> 'context', '{}'::jsonb) || case when e ? 'offers' then jsonb_build_object('offers', e -> 'offers') else '{}'::jsonb end,
         e -> 'expect', e ->> 'note', array(select jsonb_array_elements_text(e -> 'tags')), 'seed', v_sort + (o - 1)::integer
